<template>
	<div class="flex h-screen items-center justify-center bg-gray-100">
		<div class="absolute top-4 left-4">
			<BrandLogo />
		</div>
		<LanguageSelector
			:selectedLanguage="selectedLanguage"
			@change-language="changeLanguage"
		/>

		<!-- Centered Box -->
		<div
			class="relative flex flex-col items-center justify-center space-y-6 p-10 bg-white rounded-xl shadow-xl border border-gray-300 w-[800px] min-h-[600px] max-h-[600px]">
			<div class="absolute top-4 left-4">
				<Breadcrumbs :items="[
					{
						label: 'Home',
						route: {
							name: 'Home',
						},
					},
					{
						label: 'Book Appointment',
						route: '/Appointment',
					},
					{
						label: 'Success',
						route: '/BookingSuccess',
					},
				]"
				/>
			</div>
			<!-- Success Icon/Image -->
			<img src="/src/assets/Success.png" alt="Success Icon" class="h-24 w-24 object-contain" />

			<!-- Success Message -->
			<p class="text-2xl font-bold text-center">
				{{ translations[selectedLanguage].appointmentBooked }}
			</p>
			<p class="text-sm text-gray-600 text-center">
				{{ translations[selectedLanguage].appointmentBookedMessage }}
			</p>

			<!-- Action Buttons -->
			<div class="flex space-x-2" v-if="!from_checkin">
				<Button
					@click="bookAnother"
					:variant="'solid'"
					:ref_for="true"
					theme="gray"
					size="lg"
				>
					{{ translations[selectedLanguage].book }}
				</Button>
			</div>
			<div class="flex space-x-2">
				<Button v-if="booking_today"
					@click="goToCheckIn"
					:variant="'subtle'"
					:ref_for="true"
					theme="gray"
					size="lg"
				>
					{{ translations[selectedLanguage].checkIn }}
				</Button>
				<Button v-if="!from_checkin"
					@click="goToHome"
					:variant="'subtle'"
					:ref_for="true"
					theme="gray"
					size="lg"
				>
					{{ translations[selectedLanguage].leave }}
				</Button>
			</div>
		</div>
		<Footer />
		<Dialog :options="{
			title: `${dialog_title}`,
			message: `${dialog_message}`,
			size: 'xl',
			icon: {
				name: 'check',
				appearance: 'success',
			},
			actions: [
				{
					label: 'OK',
					variant: 'solid',
					onClick: () => {
						route_to_home();
					}
				},
			],
		}" v-model="success_dialog" />
		<Dialog :options="{
			title: `${dialog_title}`,
			message: `${dialog_message}`,
			size: 'xl',
			icon: {
				name: 'alert-triangle',
				appearance: 'warning',
			},
			actions: [
				{
					label: 'OK',
					variant: 'solid',
				},
			],
		}" v-model="alert_dialog" />
	</div>
</template>


<script setup>
	import { useRouter, useRoute } from "vue-router";
	import { createResource, Dialog, Breadcrumbs } from "frappe-ui";
	import { ref, onMounted } from "vue";
	import LanguageSelector from '@/components/LanguageSelector.vue';
	import Footer from '@/components/Footer.vue';
	import BrandLogo from '@/components/BrandLogo.vue';

	const router = useRouter();
	const route = useRoute();

	// Define translations
	const translations = {
		en: {
			appointmentBooked: "Appointment Booked",
			appointmentBookedMessage: "The Appointment has been successfully booked.",
			checkIn: "Check In",
			leave: "I'm Done",
			book: "Book another Appointment"
		},
		ar: {
			appointmentBooked: "تم حجز الموعد",
			appointmentBookedMessage: "تم حجز الموعد بنجاح.",
			checkIn: "حجز موعد آخر",
			leave: "مغادرة",
			book: "حجز موعد آخر"
		},
		ml: {
			appointmentBooked: "അപ്പോയിന്റ് ബുക്ക് ചെയ്തു",
			appointmentBookedMessage: "അപ്പോയിന്റ് വിജയകരമായി ബുക്ക് ചെയ്യപ്പെട്ടു.",
			checkIn: "ചെക്ക് - ഇൻ",
			leave: "തിരിച്ച് പോവുക",
			book: "മറ്റൊരു അപ്പോയിൻ്റ്മെൻ്റ് ബുക്ക് ചെയ്യുക"
		},
	};

	const selectedLanguage = ref(localStorage.getItem("selectedLanguage") || "en");
	let patient_id = ref(localStorage.getItem("patient_id") || "");
	let success_dialog = ref(false);
	let alert_dialog = ref(false);
	let dialog_message = ref("");
	let dialog_title = ref("");
	let paid = ref(true);
	let practitioner = ref("");
	let appointment = ref("");
	let from_checkin = route.query.from_checkin || null;
	let booking_today = ref(false);
	let logo = ref("");
	let get_logo = createResource({
		url:"/api/method/marley_frontend.api.get_logo_image",
		method: "GET",
		makeParams() {
			return {};
		},
		onSuccess(response) {
			if (response) {
				logo.value = response;
			}
			else {
				logo.value = "https://raw.githubusercontent.com/frappe/healthcare/develop/healthcare/public/images/healthcare.svg";
			}
		},
	})
	get_logo.fetch()

  onMounted(() => {
		// Check if the booking date is today's date on component mount
		const today = new Date().toISOString().split('T')[0];
		const bookingDate = localStorage.getItem("booking_date");

		// Set isBookingToday to true if booking date matches today's date
		if (bookingDate === today) {
		booking_today.value = true;
		}
	});

	// Function to change language and save it in local storage
	const changeLanguage = (language) => {
		selectedLanguage.value = language;
		localStorage.setItem("selectedLanguage", language);
	};

	function goToHome() {
		localStorage.clear();
		router.push({ name: "Home" });
	}

	function bookAnother() {
		router.push("Appointment");
	}

	function goToCheckIn() {
		if (patient_id.value) {
			let checkin = createResource({
				url: "/api/method/marley_frontend.api.check_appointment",
				method: "GET",
				makeParams() {
					return {
						patient_id: patient_id.value,
					};
				},
				onSuccess(response) {
					localStorage.clear("booking_date")
					if (response["message"]) {
						dialog_message = `${response["message"]}`;
						dialog_title = "Message";
						success_dialog.value = true;
					} else if (response["alert"]) {
						dialog_message = response["alert"];
						dialog_title = "Alert";
						alert_dialog.value = true;
					} else if (response["route"]) {
						paid = false
						practitioner = response["practitioner"];
						appointment = response["appointment"];
						dialog_message = response["payment_message"];
						dialog_title = "Complete Payment";
						success_dialog.value = true;
					}
				},
				onError(error) {
					dialog_message = `APIError: ${error.message}`;
					dialog_title = "Error";
					alert_dialog.value = true;
				}
			});
			checkin.fetch();
		}
	}

	function route_to_home() {
		if (paid) {
			localStorage.clear();
			if (from_checkin) {
				router.push({ name: "Checkin" });
			} else {
				router.push({ name: "Home" });
			}
		} else {
			router.push({
				name: "Payment",
				query: {
					practitioner: practitioner,
					appointment: appointment
				}
			});
		}
	}
</script>
